	template <class MemoryBlockType>
	void MemoryPool<MemoryBlockType>::Clear(void)
	{
		Page *cur, *freeNext;

		if (availablePagesSize > 0)
		{
			cur = availablePages;
			while (1)
			{
				free(cur->availableStack);
				free(cur->block);
				freeNext = cur;
				cur = cur->next;
				if (cur == availablePages)
				{
					break;
				}
				free(freeNext);
			}
			free(freeNext);
		}

		if (unavailablePagesSize > 0)
		{
			cur = unavailablePages;
			while (1)
			{
