				std::vector<boost::shared_ptr<Instance>>::const_iterator end = children->end();
				std::vector<boost::shared_ptr<Instance>>::const_iterator iter = children->begin();

				for (; iter != end; iter++)
				{
					if (Type* result = dynamic_cast<Type*>((*iter).get()))
