#include <boost/thread/once.hpp>

namespace RBX
{
	template<typename Class>
	Class* ServiceProvider::create() const
	{
		Class* result = find<Class>();
		if (!result)
		{
			boost::shared_ptr<Class> service = Creatable<Instance>::create<Class>();
			result = service.get();

			static boost::once_flag flag = BOOST_ONCE_INIT;
			boost::call_once(&callDoGetClassIndex<Class>, flag);
			size_t index = doGetClassIndex<Class>();

			const_cast<ServiceProvider*>(this)->serviceArray[index] = service;
			result->setParent(const_cast<ServiceProvider*>(this));
		}
		return result;
	}

