static int panic(lua_State* L)
{
    std::string message = lua_tostring(L, -1);
    StandardOut::singleton()->print(MESSAGE_ERROR, "Unprotected error in call to Lua API (%s)\n", message.c_str());
    RBXCRASH();
    return 0;
}

