	bool lessMotor(const MotorJoint* m0, const MotorJoint* m1)
	{
		if (m0 == m1)
			return false;

		PrimitiveSort power0 = ClumpStage::getMotorPower(m0);
		PrimitiveSort power1 = ClumpStage::getMotorPower(m1);

		return (power0 == power1) ? m0 < m1 : power0 < power1;
