		Clump* clump1 = r->getPrimitive(1)->getClump();
		RBXASSERT((clump0 == NULL) != (clump1 == NULL));
		if (!clump0)
			clump0 = clump1;
		RBXASSERT(clump0);
		return PrimitiveSort(clump0->getRootPrimitive());
