	bool ClumpStage::upToDate()
	{
		return 
			anchors.empty() &&
			rigidTwos.empty() &&
			rigidOnes.empty() &&
			rigidZeros.empty() &&
			primitives.empty() &&
			motors.empty() &&
			anchoredClumps.empty() &&
			freeClumps.empty() &&
			assemblies.empty();
