typedef G3D::CoordinateFrame Result;
struct Frame {
    Matrix rotation;
    float position[3];
    Frame();
    void set(int);
};

struct Source {
    const Frame& getFrame() const;
};

extern Vec zero;
extern unsigned int zeroFlags;

struct Model {
    char pad0[0x168];
    Result transform;
    Source* source;
    char pad1[0x10];
    volatile unsigned char dirty0;
    char pad2[0x33];
    volatile unsigned char dirty1;
    char pad3[0x2f];
    volatile unsigned char dirty2;

    void update(int);
};

void Model::update(int value)
{
    if (source) {
        Frame frame;
        frame.set(value);

        if (!(zeroFlags & 1)) {
            zeroFlags |= 1;
            zero.x = 0.0f;
            zero.y = 0.0f;
            zero.z = 0.0f;
        }

        Result result(source->getFrame().rotation.transpose() * frame.rotation,zero);

        transform = result;

        dirty1 = 1;
        dirty2 = 1;
        dirty0 = 1;
    }
}

