            sandboxThread((*(Lua::ThreadRef*)((char*)this+0x13c)).thread());
            setThreadIdentity((*(Lua::ThreadRef*)((char*)this+0x13c)).thread(), Security::CmdLine);
            lua_pop((*(lua_State**)((char*)this+0x138)), 1);
        }

        L = (*(Lua::ThreadRef*)((char*)this+0x13c)).thread();
