std::string TextXmlParser::readTag()
{
	skipWhitespace();

	if ((char)buffer->sbumpc() != '<')
		throw std::runtime_error("tag expected");

	std::string tag;
	tag += '<';

	char lastChar;
	do
	{
		lastChar = buffer->sbumpc();
		tag += lastChar;
	}
	while (lastChar != '>');

	return tag;
}

std::string TextXmlParser::readFirstTag()
{
