int XmlWriter::getHandleIndex(RBX::InstanceHandle h)
{
	std::map<RBX::InstanceHandle, int>::iterator iter = handles.find(h);
	if (iter == handles.end())
	{
		int index = (int)handles.size();
		handles[h] = index;
