        {
            if (L != other.L)
            {
                boost::mutex::scoped_lock lock(*sync);

                removeRef();
                L = other.L;

                if (L)
                {
                    lua_pushthread(L);
                    threadId = luaL_ref(L, LUA_REGISTRYINDEX);
                }
            }

            if (node != other.node)
            {
                boost::mutex::scoped_lock lock(*sync);

                removeFromNode();

                node = other.node;
                addToNode();
            }

            return *this;
