            std::string directory = skyAssetFolder() + "Sky\\";
            G3D::SkyRef result = G3D::Sky::fromFile(NULL, directory, filenames, *reinterpret_cast<const bool*>(reinterpret_cast<const char*>(sky)+0x14c), 1.0);
