	void PartInstance::setPartSizeUi(const G3D::Vector3& uiSize)
	{
		destroyJoints();

		G3D::Vector3 adjustedUiSize = uiSize;

		switch (formFactor)
		{
		case BRICK:
			adjustedUiSize.y = uiSize.y * 5.0f/6.0f;
			break;
		case PLATE:
			adjustedUiSize.y = uiSize.y * 2.5f;
			break;
		}

		setPartSizeXml(uiToXmlSize(adjustedUiSize));
		safeMove();
		join();
	}

