		}
	}

	void PartInstance::setPartTypeUi(Part::PartType _type)
	{
		if (partType != Part::BLOCK_PART)
			RBXASSERT(formFactor == SYMETRIC);

		if (getPartType() != _type)
		{
			destroyJoints();

			setPartTypeXml(_type);

