		primitive->setSurfaceType(NORM_Y, STUDS);
		primitive->setSurfaceType(NORM_Y_NEG, INLET);
		primitive->setGridSize(G3D::Vector3(4.0f, 1.2f, 2.0f));
		primitive->setFriction(0.3f);
		primitive->setElasticity(0.5f);
