 virtual void render3dAdorn(Adorn*);
 virtual const std::string getCursorName()const{return cursor;}
public:
 __declspec(noinline) AxisMoveTool(Workspace*);

 virtual MouseCommand* isSticky()const{return new AxisMoveTool(workspace);}
};
bool AxisMoveTool::hitHandle(const UIEvent&e,G3D::Vector3&point,NormalId&face){
 Extents box;
 if(bounds(box)){
  if(hitMoveHandles(box,getUnitMouseRay(e),point,face))return true;
 }
 return false;
}
std::vector<boost::shared_ptr<Instance> >::const_iterator Selection::begin()const{return selection->begin();}
std::vector<boost::shared_ptr<Instance> >::const_iterator Selection::end()const{return selection->end();}
void DragUtilities::getPrimitives2(boost::shared_ptr<Instance> instance,std::vector<Primitive*>&primitives){getPrimitives(instance.get(),primitives);}
bool AxisMoveTool::bounds(Extents&box){
 ServiceClient<Selection> selection(workspace);
 std::vector<Primitive*> primitives;
 std::for_each(selection->begin(),selection->end(),boost::bind(&DragUtilities::getPrimitives2,_1,boost::ref(primitives)));
 if(primitives.size()>0){box=Dragger::computeExtents(primitives);return true;}
 return false;
}
