void AxisMoveTool::onMouseIdle(const UIEvent&e){
 ArrowToolBase::onMouseIdle(e);
 if(captured())cursor="DragCursor";
 else{
  G3D::Vector3 point;
  NormalId face;
  if(hitHandle(e,point,face))cursor="ResizeCursor";
  else cursor=ArrowToolBase::getCursorName();
 }
}
