namespace RBX { namespace Soundscape {
FMOD::Sound* Sound::get() {
 if(!fmod_sound) {
  boost::shared_ptr<const std::string> data=ContentProvider::singleton().requestContentString(id);
  if(!data) return NULL;
  FMOD_MODE mode=is3D ? FMOD_3D : FMOD_DEFAULT;
  mode |= (GameSettings::singleton().softwareSound ? FMOD_SOFTWARE : FMOD_HARDWARE) | FMOD_OPENMEMORY;
  FMOD_CREATESOUNDEXINFO info; memset(&info,0,sizeof(info));
  info.cbsize=sizeof(info); info.length=data->size();
  checkResult(system->createSound(data->c_str(),mode,&info,&fmod_sound));
 }
 return fmod_sound;
}
}}

