extern const char* sGameTool;
class GameTool:public Named<MouseCommand,&sGameTool>{
 std::string cursor;
 __declspec(noinline) bool canDrag(PartInstance*,const G3D::Vector3&);
 virtual MouseCommand* onMouseDown(const UIEvent&);
 virtual void onMouseIdle(const UIEvent&);
 virtual void onMouseHover(const UIEvent&);
 virtual const std::string getCursorName()const{return cursor;}
public:
 __declspec(noinline) GameTool(Workspace*);
 virtual MouseCommand* isSticky()const{return new GameTool(workspace);}
};
typedef char game_tool_size_3c[sizeof(GameTool)==0x3c?1:-1];
GameTool::GameTool(Workspace* w):Named<MouseCommand,&sGameTool>(w){}
template<class Tool,class Base> class TToolVerb:public Base {
public:virtual bool isChecked()const;virtual void doIt(IDataState*);
virtual MouseCommand* createTool(){return new Tool(this->dataModel->getWorkspace());}
};
