}

#include "v8datamodel/PartInstance.h"
#include "tool/PartDragTool.h"
namespace RBX {
bool GameTool::canDrag(PartInstance* part,const G3D::Vector3& point){if(!part->getPartLocked()&&!part->lockedInPlace()&&characterCanReach(point))return true;return false;}
void GameTool::onMouseIdle(const UIEvent& event){onMouseHover(event);}
void GameTool::onMouseHover(const UIEvent& event){if(event.windowSize.x&&event.windowSize.y){G3D::Vector3 point;PartInstance* part=getUnlockedPartByLocalCharacter(event,point);if(!part)cursor="ArrowFarCursor";else if(!canDrag(part,point))cursor="ArrowCursor";else cursor="DragCursor";}}
MouseCommand* GameTool::onMouseDown(const UIEvent& event){G3D::Vector3 point;PartInstance* part=getUnlockedPartByLocalCharacter(event,point);if(part&&!part->getPartLocked()&&!part->lockedInPlace()&&characterCanReach(point))return (new PartDragTool(part,point,workspace))->onMouseDown(event);return NULL;}
}

