#include "tool/ToolsArrow.h"
#include "v8datamodel/PartInstance.h"
#include "v8datamodel/Workspace.h"
#include "util/Sound.h"
namespace RBX {
extern const char* sResizeTool;
XmlState::XmlState():root(name_root){}
class UndoState:public XmlState{public:virtual void addState(XmlElement*,Instance&);};
class RedoState:public XmlState{public:__declspec(noinline) RedoState(){} virtual void addState(XmlElement*,Instance&);};
template<class T> void Parent<T>::pushFrontChild(T*child){if(!first)last=child;else child->setNextSibling(first);first=child;}
void UndoState::addState(XmlElement*element,Instance&instance){if(element){if(!element->findAttribute(name_referent))element->addAttribute(name_referent,InstanceHandle(&instance));root.pushFrontChild(element);}}
void RedoState::addState(XmlElement*element,Instance&instance){if(!element->findAttribute(name_referent))element->addAttribute(name_referent,InstanceHandle(&instance));root.pushBackChild(element);}
typedef char undo_state_size_2c[sizeof(UndoState)==0x2c?1:-1];
typedef char redo_state_size_2c[sizeof(RedoState)==0x2c?1:-1];
class ResizeTool:public Named<ArrowToolBase,&sResizeTool>{
 boost::weak_ptr<PVInstance> target;
 bool overHandle;
 NormalId face;
 G3D::Vector3 handlePosition;
 G3D::Vector2int16 mouseDownView;
 int accumulatedResize;
 unsigned int resetState;
 void findTargetPV(const UIEvent&);
 virtual MouseCommand* onMouseDown(const UIEvent&);
 virtual void onMouseMove(const UIEvent&);
 virtual MouseCommand* onMouseUp(const UIEvent&);
 virtual void onMouseHover(const UIEvent&);
 virtual void render2d(Adorn*);
 virtual void render3dAdorn(Adorn*);
 virtual const std::string getCursorName()const;
 virtual void writeSize(XmlState*);
 void resize(int);
public:
 __declspec(noinline) ResizeTool(Workspace*);
 virtual MouseCommand* isSticky()const{return new ResizeTool(workspace);}
};
MouseCommand*ResizeTool::onMouseDown(const UIEvent&e){
 findTargetPV(e);
 if(target.expired())return ArrowToolBase::onMouseDown(e);
 mouseDownView=e.mousePosition;
 accumulatedResize=0;resetState=0;overHandle=true;
 capture();
 undoState.reset(new UndoState());
 writeSize(undoState.get());
 return this;
}
MouseCommand*ResizeTool::onMouseUp(const UIEvent&){
 if(captured()){
  releaseCapture();
  if(!target.expired()){
   std::auto_ptr<XmlState> redo(new RedoState());
   writeSize(redo.get());
   workspace->getDataState().pushState(getName().toString(),undoState.release(),redo.release());
   workspace->getDataState().setDirty(true);
  }
 }
 return NULL;
}
typedef char resize_tool_size_4c[sizeof(ResizeTool)==0x4c?1:-1];
ResizeTool::ResizeTool(Workspace*w):Named<ArrowToolBase,&sResizeTool>(w),overHandle(false),accumulatedResize(0),resetState(0){}
const std::string ResizeTool::getCursorName()const{return overHandle?std::string("ResizeCursor"):ArrowToolBase::getCursorName();}
void ResizeTool::writeSize(XmlState*state){if(PartInstance*part=dynamic_cast<PartInstance*>(target.lock().get()))part->writeSize(state);}
void ResizeTool::onMouseHover(const UIEvent&e){findTargetPV(e);overHandle=!target.expired();ArrowToolBase::onMouseHover(e);}
void ResizeTool::resize(int amount){if(!target.expired()){
 PartInstance* part=static_cast<PartInstance*>(target.lock().get());
 part->destroyJoints();
 if(part->resize(face,amount))ServiceProvider::create<Soundscape::SoundService>(workspace)->playSound(CLICK_SOUND);
 part->join();
}}
}

