		Primitive* prim1,
		const G3D::CoordinateFrame& _jointCoord0,
		const G3D::CoordinateFrame& _jointCoord1)
		: Edge(prim0, prim1),
		  assoc()
	{
		jointCoord0 = Math::snapToGrid(_jointCoord0, 0.1f);
		jointCoord1 = Math::snapToGrid(_jointCoord1, 0.1f);
	}

