			RBXASSERT(newRbxSize.max(G3D::Vector3(1.0f, 0.4f, 1.0f)) == newRbxSize);

			if (legacyOffset.get())
			{
				G3D::CoordinateFrame oldCorner = primitive->getGridCorner();
				primitive->setGridSize(newRbxSize);
				primitive->setGridCorner(oldCorner);
