	}


	G3D::Vector3 PartInstance::uiToXmlSize(const G3D::Vector3& uiSize) const
	{
		G3D::Vector3 gridUiSize = Math::iRoundVector3(uiSize.max(G3D::Vector3(1.0f, 1.0f, 1.0f)));
		G3D::Vector3 xmlSize = gridUiSize;

		switch (formFactor)
		{
		case BRICK:
			xmlSize.y *= 1.2f;
			break;
		case PLATE:
			xmlSize.y *= 0.4f;
			break;
		}

		return xmlSize;
