	G3D::Vector3 Primitive::clipToSafeSize(const G3D::Vector3& newSize)
	{
		G3D::Vector3 r = newSize.min(G3D::Vector3(512.0f, 512.0f, 512.0f));

		if (r.x * r.y * r.z > 1e+6f) 
		{
			r.y = floorf(1e+6f / (r.x * r.z));
		}

		return r;
