#include "gui/ScoreHud.h"
#include "util/Color.h"
#include <G3D/Table.h>
__declspec(noinline) unsigned int hashCode(const std::string&);
namespace RBX {
BoardData::BoardData(){}
void ScoreHud::renderFFALeaderboard(Adorn*adorn){
 bool hasStats=true;
 BoardData data;BuildBoardData(data);
 if(data.fields.size()==0)return;
 if(data.fields.size()==1)hasStats=false;
 G3D::Rect2D viewport=adorn->getViewport();
 float viewportWidth=viewport.width();
 float scale=viewportWidth/1024.0f;
 float row=14.0f*scale;
 float width=viewportWidth*.33f;if(!hasStats)width*=.5f;
 setGuiSize(G3D::Vector2(width,(data.data.size()+2.5f)*row));
 Rect rect=getMyRect();adorn->rect2d(rect.toRect2D(),GuiItem::translucentBackdrop());
 for(size_t col=0;col<data.fields.size();++col){
  float extent=rect.high.x-rect.low.x;
  G3D::Vector2 position=rect.low;
  if(col)position.x+=extent*.5f+extent*.5f/data.fields.size()*(col-1);
  adorn->drawFont2D(data.fields[col],position,row,G3D::Color3::white(),G3D::Color4::clear(),Adorn::XALIGN_LEFT,Adorn::YALIGN_TOP,Adorn::PROPORTIONAL_SPACING);
 }
 rect.low.y+=row*2;
 for(size_t col=0;col<data.fields.size();++col){
  for(size_t index=0;index<data.data.size();++index){
   G3D::Color3 color=G3D::Color3::white();
   if(!col)color=Color::colorFromIndex8(hashCode(data.data[index][0])%8);
   float extent=rect.high.x-rect.low.x;
   G3D::Vector2 position=rect.low;
   if(col)position.x+=extent*.5f+extent*.5f/data.fields.size()*(col-1);
   position.y+=index*row;
   adorn->drawFont2D(data.data[index][col],position,row,color,G3D::Color4::clear(),Adorn::XALIGN_LEFT,Adorn::YALIGN_TOP,Adorn::PROPORTIONAL_SPACING);
  }
 }
}
}

