	static ATL::CPath getLocalCachePath(bool createPath)
	{
		ATL::CPath path;

		if (createPath)
		{
			static std::string s = FileSystem::getCacheDirectory(true);
			path.m_strPath.SetString(s.c_str());
		}
		else
		{
