	void Humanoid::setWalkDirection(const G3D::Vector3& value)
	{
		if ((*reinterpret_cast<G3D::Vector3*>(reinterpret_cast<char*>(this)+0x1d0)) != value)
		{
			if (value == G3D::Vector3::zero())
			{
