		: mousePart(shared_from(mousePartPtr)),
		  dragParts(),
		  joined(true),
		  rootInstance(rootInstance),
          contactManager(rootInstance->getWorld()->getContactManager())
	{
		DragUtilities::pvsToParts(pvInstances, dragParts);
