		{
			if (instance)
			{
				Guid::Data id;
				instance->getGuid().extract(id);

				if (!scopeNames.trySend(stream, id.scope->name))
					return false;

				RBXASSERT((id.index & 0xff000000) == 0);
				stream.WriteBits((unsigned char*)&id.index, 24);
				return true;
			}
