		}

		void IdSerializer::deserializeId(RakNet::BitStream& stream, Guid::Data& id)
		{
			scopeNames.receive(stream, id.scope);
			if (*id.scope != Name::getNullName())
			{
				id.index = 0;
				stream.ReadBits((unsigned char*)&id.index, 24);
			}
			else
			{
				id.index = 0;
