namespace RBX {namespace Network {
void Replicator::connectToReplicationContainers(){
 std::vector<boost::signals::connection>::iterator connectionEnd=replicationContainerConnections.end();
 for(std::vector<boost::signals::connection>::iterator iter=replicationContainerConnections.begin();iter!=connectionEnd;++iter)iter->disconnect();
 replicationContainerConnections.clear();
 std::vector<Instance*>::iterator end=replicationContainers.end();
 for(std::vector<Instance*>::iterator iter=replicationContainers.begin();iter!=end;++iter){
  if(*iter && wantReplicate(*iter)){
   replicationContainerConnections.push_back(Instance::event_descendentAdded.connect(*iter,boost::bind(&Replicator::onDescendentAdded,this,_1)));
   replicationContainerConnections.push_back(Instance::event_descendentRemoving.connect(*iter,boost::bind(&Replicator::onDescendentRemoving,this,_1)));
   (*iter)->visitDescendents(boost::bind(&Replicator::onDescendentAdded,this,_1));
  }
 }
