static __declspec(noinline) int __fastcall orderedCompare(const G3D::Vector3& a, const G3D::Vector3& b)
{
	if (a.x < b.x)
		return -1;
	if (a.x > b.x)
		return 1;

	if (a.y < b.y)
		return -1;
	if (a.y > b.y)
		return 1;

	if (a.z < b.z)
		return -1;
	if (a.z > b.z)
		return 1;

	return 0;
}

