		void RenderScene::updateShadowVAR(const G3D::Array<G3D::Vector3>& shadowVertex)
		{
			size_t size = shadowVertex.size() * 12 + 16;
			if (shadowVARArea.isNull() || shadowVARArea->totalSize() < size)
			{
				shadowVARArea = G3D::VARArea::create(size);
