                         "numTextureUnits                       = %d\n"
                         "glGet(GL_MAX_TEXTURE_UNITS_ARB)       = %d\n"
                         "glGet(GL_MAX_TEXTURE_IMAGE_UNITS_ARB) = %d\n",
