    /**
     C++ STL style iterator variable.  See begin().
     */
    class Iterator {
    private:
        friend class Table<Key, Value>;

        /**
         Bucket index.
         */
        int                index;

        /**
         Linked list node.
         */
        Node*              node;
        Table<Key, Value>* table;
        int                numBuckets;
