    void set(const Key& key, const Value& value) {
        unsigned int code = ::hashCode(key);
        unsigned int b = code % numBuckets;

        // Go to the bucket
        Node* n = bucket[b];

        // No bucket, so this must be the first
        if (n == NULL) {
            bucket[b] = new Node(key, value, code, NULL);
            ++_size;
            return;
