	if ( data == 0 || lengths == 0 )
		return 0;

	if ( remoteSystemList == 0 || *((volatile unsigned char*)this + 4) == true )
		return 0;

	if (numParameters==0)
		return 0;

	if (lengths==0)
		return 0;

	if ( broadcast == false && systemIdentifier.IsUndefined() )
		return 0;

	uint32_t usedSendReceipt;
	if (forceReceiptNumber!=0)
