    double VBOTime;
    double RAMTime;

    glPushAttrib(GL_ALL_ATTRIB_BITS);
    glPushClientAttrib(GL_ALL_CLIENT_ATTRIB_BITS);

    glPushAttrib(GL_ALL_ATTRIB_BITS);
