        // CLFLUSH_InstructionCacheLineSize                                     = (ebxreg >> 8) & 0xFF;
        // DS_DebugStore                                                                        = checkBit(features, 21);
        // ACPI_ThermalMonitorAndClockControl                           = checkBit(features, 22);
        _mmx                                                                                            = checkBit(features, 23);
