}

bool RegistryUtil::writeInt32(const std::string& key, int32 valueData) {

    size_t pos = key.find('\\', 0);
    if ( pos == std::string::npos ) {
        return false;
    }

    HKEY hkey = getKeyFromString(key.c_str(), pos);

