std::string BinaryInput::readString(int n) {
    prepareToRead(n);
    debugAssertM((pos + n) <= length, "Read past end of file");

    char *s = (char*)System::malloc(n + 1);
    assert(s != NULL);

    memcpy(s, buffer + pos, n);
    // There may not be a null, so make sure
    // we add one.
    s[n] = '\0';

    std::string out = s;
    System::free(s);
    s = NULL;

    pos += n;

