void BinaryInput::loadIntoMemory(int startPosition, int minLength) {
    // Load the next section of the file
    debugAssertM(filename != "<memory>", "Read past end of file.");

    int absPos = alreadyRead + pos;

    if (bufferLength < minLength) {
