    class VRbxFont
    {
    public:
        enum XAlign
        {
            XALIGN_RIGHT,
            XALIGN_LEFT,
            XALIGN_CENTER
        };

        enum YAlign
        {
            YALIGN_BOTTOM,
            YALIGN_BASELINE,
            YALIGN_CENTER,
            YALIGN_TOP
        };

        enum Spacing
        {
            PROPORTIONAL_SPACING,
            FIXED_SPACING
        };

    private:
        int subWidth[128];
        int charWidth;
        int charHeight;
        int baseline;
        TexturePtr texture;

        G3D::Vector2 computePackedArray(
            const std::string& s,
            double x,
            double y,
            double w,
            double h,
            Spacing spacing,
            G3D::Vector2* array) const;

        G3D::Vector2 get2DStringBounds(
            const std::string& s,
            double size,
            Spacing spacing) const;

    public:
        G3D::Vector2 draw2D(
            TwoDManager* manager,
            const std::string& s,
            const G3D::Vector2& pos2D,
            double size,
            const G3D::Color4& color,
            const G3D::Color4& border,
            XAlign xalign,
            YAlign yalign,
            Spacing spacing) const;
