#pragma intrinsic(_InterlockedDecrement)
namespace rbx {
class sp_counted_base {
public:
	virtual ~sp_counted_base();
	virtual void dispose() = 0;
	virtual void destroy();
	void release() {
		if (_InterlockedDecrement(&use_count_) == 0) {
			dispose();
			weak_release();
		}
	}
	void weak_release() {
		if (_InterlockedDecrement(&weak_count_) == 0)
			destroy();
	}
	long use_count_;
	long weak_count_;
};
struct ExtraSpace {
	int* counter;
	sp_counted_base* pi;
	int resume;
};
