LRESULT CXTColorPageCustom::OnUpdateColor(WPARAM wParam, LPARAM lParam)
{
	COLORREF clr = (COLORREF)wParam;

	if ((HWND)lParam == m_colorWnd)
	{
		int nL;
		RGBtoHSL(clr, &nL, &m_nS, &m_nH);
